UPDATE businesses SET description = 'Kasfin (Eiendoms) Beperk is an authorised financial services provider operating as a short-term insurance brokerage from Moregloed, Pretoria. The brokerage was established by members of the Oranjekas group to give clients a single point of contact for arranging short-term insurance, and forms part of a wider community-economic initiative known as the Oranje project. Kasfin negotiates and places cover with a range of insurance companies, including AIG, Auto & General, CIA, One Com, Santam and Unity, giving clients access to multiple insurers through one broker rather than dealing with each insurer directly. Its product range covers personal comprehensive insurance, liability cover, engineering insurance, commercial insurance and commercial vehicle cover, as well as guarantees and watercraft insurance. The brokerage says it aims to serve clients in their own language and in a professional manner, reflecting its roots as an insurance service built specifically for the Oranjekas community before extending its offering across these broader personal and commercial insurance lines.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.dievryburger.co.za/2013/11/promosie-kasfin-edms-bpk/'), description_enriched_at = datetime('now') WHERE slug = 'kasfin-eiendoms-beperk-moregloed' AND description = 'Kasfin (Eiendoms) Beperk is a licensed authorised financial services provider operating as a short-term insurance brokerage, arranging personal, commercial, liability, engineering and watercraft insurance through contracts with multiple insurers.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
